class Solution {
public:
    long long putMarbles(std::vector<int>& weights, int k) {
        int n = weights.size();
        if (k == 1 || k == n) return 0;
        std::vector<long long> pairs(n - 1);
        for (int i = 0; i < n - 1; ++i) {
            pairs[i] = (long long)weights[i] + weights[i + 1];
        }
        std::sort(pairs.begin(), pairs.end());
        long long min_sum = 0, max_sum = 0;
        for (int i = 0; i < k - 1; ++i) {
            min_sum += pairs[i];
            max_sum += pairs[n - 2 - i];
        }
        return max_sum - min_sum;
    }
};

class Solution {
    public long putMarbles(int[] weights, int k) {
        int n = weights.length;
        if (k == 1 || k == n) return 0;
        long[] pairs = new long[n - 1];
        for (int i = 0; i < n - 1; i++) {
            pairs[i] = (long)weights[i] + weights[i + 1];
        }
        java.util.Arrays.sort(pairs);
        long minSum = 0, maxSum = 0;
        for (int i = 0; i < k - 1; i++) {
            minSum += pairs[i];
            maxSum += pairs[n - 2 - i];
        }
        return maxSum - minSum;
    }
}

